import React, { useState, useEffect, useCallback } from 'react';
import api from '../../api';

const StockDetails = ({ symbol }) => {
    const [stockInfo, setStockInfo] = useState(null);
    const [loading, setLoading] = useState(true);

    const fetchStockDetails = useCallback(async () => {
        if (!symbol) return;
        try {
            const data = await api.getStockInfo(symbol);
            setStockInfo(data);
        } catch (error) {
            console.error('Error fetching stock info:', error);
        }
        setLoading(false);
    }, [symbol]);

    useEffect(() => {
        if (symbol) {
            setLoading(true);
            fetchStockDetails();
            const interval = setInterval(fetchStockDetails, 5000); // Dynamic 5-second live tick polling
            return () => clearInterval(interval);
        }
    }, [symbol, fetchStockDetails]);

    if (loading && !stockInfo) {
        return (
            <div className="soft-card" style={{ padding: '24px', textAlign: 'center', color: 'var(--text-secondary)' }}>
                Loading live quote for {symbol}...
            </div>
        );
    }

    if (!stockInfo) return null;

    const price = stockInfo.price || 0;
    const prevClose = stockInfo.prev_close || (price > 0 ? price : 1);

    // Dynamic recalculation of change & percentage change as live tick price moves
    const change = stockInfo.change !== undefined && stockInfo.change !== null 
        ? stockInfo.change 
        : (price && prevClose ? price - prevClose : 0);

    const changePercent = stockInfo.change_percent !== undefined && stockInfo.change_percent !== null 
        ? stockInfo.change_percent 
        : (prevClose ? (change / prevClose) * 100 : 0);

    const isPositive = change >= 0;

    return (
        <div className="soft-card fade-in" style={{ padding: '24px', marginBottom: '20px' }}>
            <div style={{ 
                display: 'flex', 
                justifyContent: 'space-between', 
                alignItems: 'flex-start', 
                flexWrap: 'wrap',
                gap: '16px'
            }}>
                <div>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                        <h1 style={{ color: 'var(--text-primary)', margin: 0, fontSize: '26px', fontWeight: '800' }}>
                            {stockInfo.symbol}
                        </h1>
                        <span className="soft-badge" style={{ background: '#1e2c45', color: 'var(--accent-primary)' }}>
                            NSE
                        </span>
                        <span className="soft-badge" style={{ background: '#1e2c45', color: 'var(--accent-secondary)' }}>
                            BSE
                        </span>
                    </div>
                    <div style={{ color: 'var(--text-secondary)', fontSize: '15px', fontWeight: '600', marginTop: '4px' }}>
                        {stockInfo.name || stockInfo.symbol}
                    </div>
                    <div style={{ color: 'var(--text-muted)', fontSize: '13px', marginTop: '2px' }}>
                        {stockInfo.sector} · {stockInfo.industry}
                    </div>
                </div>

                <div style={{ textAlign: 'right' }}>
                    <div style={{ fontSize: '32px', fontWeight: '800', color: 'var(--text-primary)', letterSpacing: '-0.02em' }}>
                        ₹{price ? price.toLocaleString('en-IN', { minimumFractionDigits: 2 }) : '---'}
                    </div>
                    <div style={{ 
                        fontSize: '16px', 
                        fontWeight: '700',
                        color: isPositive ? 'var(--accent-emerald)' : 'var(--accent-rose)',
                        marginTop: '4px',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'flex-end',
                        gap: '6px'
                    }}>
                        <span>{isPositive ? '▲' : '▼'}</span>
                        <span>{isPositive ? '+' : ''}{change.toFixed(2)}</span>
                        <span>({isPositive ? '+' : ''}{changePercent.toFixed(2)}%)</span>
                        <span style={{ fontSize: '11px', color: 'var(--text-muted)', fontWeight: '500' }}>LIVE</span>
                    </div>
                </div>
            </div>

            {/* Key Statistics Grid */}
            <div style={{
                display: 'grid',
                gridTemplateColumns: 'repeat(auto-fit, minmax(130px, 1fr))',
                gap: '12px',
                marginTop: '20px',
                paddingTop: '20px',
                borderTop: '1px solid var(--border-color)'
            }}>
                <div style={{ background: '#111927', padding: '12px', borderRadius: 'var(--radius-sm)' }}>
                    <div style={{ color: 'var(--text-muted)', fontSize: '11px', fontWeight: '700', textTransform: 'uppercase' }}>Day Low / High</div>
                    <div style={{ color: 'var(--text-primary)', fontSize: '13px', fontWeight: '700', marginTop: '4px' }}>
                        ₹{stockInfo.day_low || '---'} / ₹{stockInfo.day_high || '---'}
                    </div>
                </div>

                <div style={{ background: '#111927', padding: '12px', borderRadius: 'var(--radius-sm)' }}>
                    <div style={{ color: 'var(--text-muted)', fontSize: '11px', fontWeight: '700', textTransform: 'uppercase' }}>52W Low / High</div>
                    <div style={{ color: 'var(--text-primary)', fontSize: '13px', fontWeight: '700', marginTop: '4px' }}>
                        ₹{stockInfo['52w_low'] || '---'} / ₹{stockInfo['52w_high'] || '---'}
                    </div>
                </div>

                <div style={{ background: '#111927', padding: '12px', borderRadius: 'var(--radius-sm)' }}>
                    <div style={{ color: 'var(--text-muted)', fontSize: '11px', fontWeight: '700', textTransform: 'uppercase' }}>Market Cap</div>
                    <div style={{ color: 'var(--text-primary)', fontSize: '13px', fontWeight: '700', marginTop: '4px' }}>
                        {stockInfo.market_cap ? `₹${(stockInfo.market_cap / 10000000).toFixed(0)} Cr` : 'N/A'}
                    </div>
                </div>

                <div style={{ background: '#111927', padding: '12px', borderRadius: 'var(--radius-sm)' }}>
                    <div style={{ color: 'var(--text-muted)', fontSize: '11px', fontWeight: '700', textTransform: 'uppercase' }}>P/E Ratio</div>
                    <div style={{ color: 'var(--text-primary)', fontSize: '13px', fontWeight: '700', marginTop: '4px' }}>
                        {stockInfo.pe_ratio ? stockInfo.pe_ratio.toFixed(2) : 'N/A'}
                    </div>
                </div>

                <div style={{ background: '#111927', padding: '12px', borderRadius: 'var(--radius-sm)' }}>
                    <div style={{ color: 'var(--text-muted)', fontSize: '11px', fontWeight: '700', textTransform: 'uppercase' }}>Div Yield</div>
                    <div style={{ color: 'var(--text-primary)', fontSize: '13px', fontWeight: '700', marginTop: '4px' }}>
                        {stockInfo.dividend_yield ? `${stockInfo.dividend_yield.toFixed(2)}%` : 'N/A'}
                    </div>
                </div>

                <div style={{ background: '#111927', padding: '12px', borderRadius: 'var(--radius-sm)' }}>
                    <div style={{ color: 'var(--text-muted)', fontSize: '11px', fontWeight: '700', textTransform: 'uppercase' }}>EPS (TTM)</div>
                    <div style={{ color: 'var(--text-primary)', fontSize: '13px', fontWeight: '700', marginTop: '4px' }}>
                        {stockInfo.eps ? `₹${stockInfo.eps.toFixed(2)}` : 'N/A'}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default StockDetails;
